  KEY `idx_gb_ai_wsq_scene_status` (`gb_ai_wsq_scene`,`gb_ai_wsq_status`,`gb_ai_wsq_enabled`),
  CONSTRAINT `fk_gb_ai_wsq_workflow` FOREIGN KEY (`gb_ai_wsq_workflow_id`) REFERENCES `gb_ai_workflow` (`gb_ai_workflow_id`)
) ENGINE=InnoDB AUTO_INCREMENT=203 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Workflow 推荐问句（老板常问/试问问题）';

