  `gb_DPG_dis_goods_great_id` int DEFAULT NULL,
  `gb_DPG_orders_weight_amount` int DEFAULT NULL COMMENT '订单采购的订单数量',
  PRIMARY KEY (`gb_distributer_purchase_goods_id`) USING BTREE
