INSERT INTO `gb_ai_message` (`gb_ai_message_id`, `gb_ai_message_conversation_id`, `gb_ai_message_role`, `gb_ai_message_content`, `gb_ai_message_token_count`, `gb_ai_message_run_id`, `gb_ai_message_status`, `gb_ai_message_cards_json`, `gb_ai_message_context_summary_json`, `gb_ai_message_create_time`, `gb_ai_message_update_time`, `gb_ai_message_user_id`) VALUES (298, 92, 'assistant', '已根据当前菜单数据整理优化方案，重点分组与本周建议请查看下方卡片。', 0, 1780395386697, 'COMPLETED', '[{\"title\": \"菜单优化方案\", \"source\": {\"dataRef\": \"menuOptimizationPlan\", \"answerPlan\": \"menuOperationAnswerPlan\", \"presentationSource\": \"llm_expert_presentation\"}, \"payload\": {\"status\": \"ACTIVE\", \"summary\": \"上个月酸奶碗是菜单中唯一菜品，销量和利润表现非常突出，但理论成本与实际成本存在较大偏差，建议优先复核成本与配方执行。\", \"nextSteps\": [\"本周先核对「酸奶碗」的标准配方用量与实际出库量是否一致\", \"检查后厨是否按标准执行，是否存在用料不足或损耗偏差\"], \"detailData\": {\"evidenceRows\": [{\"unit\": \"元\", \"value\": \"35226\", \"fieldPath\": \"businessInsightSummary.totalListPriceRevenue\", \"evidenceId\": \"ev-portfolio-revenue\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"标价销售额\"}, {\"value\": \"98.08%\", \"fieldPath\": \"businessInsightSummary.comprehensiveGrossMarginRateOnListPrice\", \"evidenceId\": \"ev-portfolio-margin\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"综合毛利率\"}, {\"unit\": \"元\", \"value\": \"9041.34\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-portfolio_star-3\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"酸奶碗 实际利润(type123)\"}, {\"unit\": \"元\", \"value\": \"9041.34\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-opt_cost_review_fallback-4\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"酸奶碗 实际利润(type123)\"}, {\"unit\": \"元\", \"value\": \"9041.34\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-opt_protect-5\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"酸奶碗 实际利润(type123)\"}], \"protectDishes\": [{\"dishId\": \"8\", \"reason\": \"销量高于本轮中位，实际利润不低于本轮中位（type123）\", \"dishName\": \"酸奶碗\", \"quadrantCode\": \"STAR\", \"quadrantName\": \"明星菜\", \"evidenceRefId\": \"ev-dish-opt_protect-5\", \"listPriceRevenue\": \"9270.00\", \"soldPortionsTotal\": \"309.00\", \"actualProfitAmount\": \"9041.34\", \"suggestedActionLabel\": \"继续主推\", \"blendedGrossMarginRateOnListPrice\": \"97.53%\"}], \"priorityGroups\": [{\"dishes\": [{\"dishId\": \"8\", \"reason\": \"毛利率偏低或实际利润为负，建议复核成本与定价\", \"dishName\": \"酸奶碗\", \"evidenceRefId\": \"ev-dish-opt_cost_review_fallback-4\", \"listPriceRevenue\": \"9270.00\", \"soldPortionsTotal\": \"309.00\", \"actualProfitAmount\": \"9041.34\", \"suggestedActionLabel\": \"复核成本\", \"blendedGrossMarginRateOnListPrice\": \"97.53%\"}], \"reason\": \"相对引流档或毛利/利润偏弱的菜，优先复核成本、用量与定价\", \"priority\": 1, \"groupCode\": \"PRIORITY_HANDLE\", \"groupName\": \"优先处理\", \"suggestedAction\": \"复核成本与定价\"}, {\"dishes\": [{\"dishId\": \"8\", \"reason\": \"销量高于本轮中位，实际利润不低于本轮中位（type123）\", \"dishName\": \"酸奶碗\", \"quadrantCode\": \"STAR\", \"quadrantName\": \"明星菜\", \"evidenceRefId\": \"ev-dish-opt_protect-5\", \"listPriceRevenue\": \"9270.00\", \"soldPortionsTotal\": \"309.00\", \"actualProfitAmount\": \"9041.34\", \"suggestedActionLabel\": \"继续主推\", \"blendedGrossMarginRateOnListPrice\": \"97.53%\"}], \"reason\": \"明星菜利润与销量贡献稳定，建议保供并维持推荐位\", \"priority\": 2, \"groupCode\": \"STABLE_PROMOTE\", \"groupName\": \"稳定主推\", \"suggestedAction\": \"继续主推\"}], \"promotionDishes\": [], \"watchListDishes\": [], \"costReviewDishes\": [{\"dishId\": \"8\", \"reason\": \"毛利率偏低或实际利润为负，建议复核成本与定价\", \"dishName\": \"酸奶碗\", \"evidenceRefId\": \"ev-dish-opt_cost_review_fallback-4\", \"listPriceRevenue\": \"9270.00\", \"soldPortionsTotal\": \"309.00\", \"actualProfitAmount\": \"9041.34\", \"suggestedActionLabel\": \"复核成本\", \"blendedGrossMarginRateOnListPrice\": \"97.53%\"}], \"optimizationSummary\": \"本月菜单优化重点：先复核相对引流档（畅销低利）菜的成本与定价，同时稳定明星菜供应与推荐位。\"}, \"keyFindings\": [\"酸奶碗销量与利润均排名第一，是当前菜单的核心产品。\", \"实际毛利率高达97.53%，但理论毛利率仅为62.77%，两者相差近35个百分点，成本控制存在异常。\"], \"mainSummary\": \"上个月酸奶碗是菜单中唯一菜品，销量和利润表现非常突出，但理论成本与实际成本存在较大偏差，建议优先复核成本与配方执行。\", \"focusSections\": [{\"dishes\": [{\"reason\": \"实际毛利率97.53%与理论毛利率62.77%偏差过大，需排查用量、出库或损耗环节\", \"dishName\": \"酸奶碗\", \"suggestedAction\": \"复核成本与配方\", \"actualProfitAmount\": \"9041.34\", \"blendedGrossMarginRateOnListPrice\": \"97.53%\"}], \"reason\": \"成本偏差是影响利润稳定性的关键风险点\", \"sectionTitle\": \"成本异常优先处理\", \"sectionSummary\": \"实际成本远低于理论成本，可能存在配方执行偏差、用量不准或出库记录问题，是当前最大优化空间。\", \"suggestedAction\": \"本周先核对酸奶碗的标准配方、实际用量与出库记录\"}], \"detailDataScope\": \"harness_only\", \"detailDataVisible\": false, \"presentationSource\": \"llm_expert_presentation\", \"supportingEvidence\": [{\"unit\": \"道\", \"value\": \"1\", \"displayLabel\": \"分析菜品数\"}, {\"unit\": \"份\", \"value\": \"309\", \"displayLabel\": \"总销量\"}, {\"unit\": \"元\", \"value\": \"9270\", \"displayLabel\": \"总销售额\"}, {\"unit\": \"元\", \"value\": \"9041.34\", \"displayLabel\": \"实际总利润\"}, {\"unit\": \"\", \"value\": \"97.53%\", \"displayLabel\": \"实际毛利率\"}, {\"unit\": \"\", \"value\": \"62.77%\", \"displayLabel\": \"理论毛利率\"}], \"capabilityBoundaryZh\": \"当前版本暂不提供最新采购价、外部市场比价、连续多周期趋势、跨门店排名和套餐点单组合分析。\"}, \"cardType\": \"MENU_ACTION_RECOMMENDATION_CARD\", \"subtitle\": \"基于四象限分层与销量、毛利、实际利润生成的优先级建议\", \"chartType\": \"PLAN\"}]', '{\"timeText\": \"2026-05-01～2026-05-31\", \"scopeText\": \"本门店\", \"storeText\": \"汀兰餐厅\", \"contextBar\": \"汀兰餐厅 · 05/01–05/31 · 本门店\", \"dateRangeText\": \"05/01–05/31\", \"permissionScopeText\": \"本门店\"}', '2026-06-02 19:13:12', '2026-06-02 19:13:12', 2);
