INSERT INTO `gb_ai_message` (`gb_ai_message_id`, `gb_ai_message_conversation_id`, `gb_ai_message_role`, `gb_ai_message_content`, `gb_ai_message_token_count`, `gb_ai_message_run_id`, `gb_ai_message_status`, `gb_ai_message_cards_json`, `gb_ai_message_context_summary_json`, `gb_ai_message_create_time`, `gb_ai_message_update_time`, `gb_ai_message_user_id`) VALUES (304, 92, 'assistant', '已根据当前菜单数据整理优化方案，重点分组与本周建议请查看下方卡片。', 0, 1780395386700, 'COMPLETED', '[{\"title\": \"菜单优化方案\", \"source\": {\"dataRef\": \"menuOptimizationPlan\", \"answerPlan\": \"menuOperationAnswerPlan\", \"presentationSource\": \"llm_expert_presentation\"}, \"payload\": {\"status\": \"ACTIVE\", \"summary\": \"上个月汀兰餐厅整体毛利表现非常好，但四道菜中有两道菜的理论成本与实际成本差距较大，这是当前最值得关注的问题。\", \"nextSteps\": [\"本周先核对酸奶碗的成本核算方式，确认理论成本与实际成本差距大的原因\", \"保持椒麻鸡的现有出品和推荐位，暂不调整\", \"观察香煎青鱼下个月销量是否有自然增长，再决定是否调整菜单位置\"], \"detailData\": {\"evidenceRows\": [{\"unit\": \"元\", \"value\": \"35226\", \"fieldPath\": \"businessInsightSummary.totalListPriceRevenue\", \"evidenceId\": \"ev-portfolio-revenue\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"标价销售额\"}, {\"value\": \"98.08%\", \"fieldPath\": \"businessInsightSummary.comprehensiveGrossMarginRateOnListPrice\", \"evidenceId\": \"ev-portfolio-margin\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"综合毛利率\"}, {\"unit\": \"元\", \"value\": \"10015.22\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-portfolio_star-3\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"椒麻鸡 实际利润(type123)\"}, {\"unit\": \"元\", \"value\": \"9041.34\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-portfolio_traffic-4\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"酸奶碗 实际利润(type123)\"}, {\"unit\": \"元\", \"value\": \"9840.18\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-portfolio_potential-5\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"香煎青鱼 实际利润(type123)\"}, {\"unit\": \"元\", \"value\": \"5651.52\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-portfolio_eliminate-6\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"核桃芽菜西芹 实际利润(type123)\"}, {\"unit\": \"元\", \"value\": \"9041.34\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-opt_cost_review-7\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"酸奶碗 实际利润(type123)\"}, {\"unit\": \"元\", \"value\": \"10015.22\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-opt_protect-8\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"椒麻鸡 实际利润(type123)\"}, {\"unit\": \"元\", \"value\": \"9840.18\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-opt_promotion-9\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"香煎青鱼 实际利润(type123)\"}, {\"unit\": \"元\", \"value\": \"5651.52\", \"fieldPath\": \"dishRows.actualProfitAmount123\", \"evidenceId\": \"ev-dish-opt_watch-10\", \"sourceTool\": \"dish_profit_analysis\", \"displayLabel\": \"核桃芽菜西芹 实际利润(type123)\"}], \"protectDishes\": [{\"dishId\": \"6\", \"reason\": \"销量高于本轮中位，实际利润不低于本轮中位（type123）\", \"dishName\": \"椒麻鸡\", \"quadrantCode\": \"STAR\", \"quadrantName\": \"明星菜\", \"evidenceRefId\": \"ev-dish-opt_protect-8\", \"listPriceRevenue\": \"10160.00\", \"soldPortionsTotal\": \"254.00\", \"actualProfitAmount\": \"10015.22\", \"suggestedActionLabel\": \"继续主推\", \"blendedGrossMarginRateOnListPrice\": \"98.58%\"}], \"priorityGroups\": [{\"dishes\": [{\"dishId\": \"8\", \"reason\": \"相对引流档（畅销低利），优先复核成本、用量与损耗\", \"dishName\": \"酸奶碗\", \"quadrantCode\": \"TRAFFIC\", \"quadrantName\": \"引流菜\", \"evidenceRefId\": \"ev-dish-opt_cost_review-7\", \"listPriceRevenue\": \"9270.00\", \"soldPortionsTotal\": \"309.00\", \"actualProfitAmount\": \"9041.34\", \"suggestedActionLabel\": \"复核成本\", \"blendedGrossMarginRateOnListPrice\": \"97.53%\"}], \"reason\": \"相对引流档或毛利/利润偏弱的菜，优先复核成本、用量与定价\", \"priority\": 1, \"groupCode\": \"PRIORITY_HANDLE\", \"groupName\": \"优先处理\", \"suggestedAction\": \"复核成本与定价\"}, {\"dishes\": [{\"dishId\": \"6\", \"reason\": \"销量高于本轮中位，实际利润不低于本轮中位（type123）\", \"dishName\": \"椒麻鸡\", \"quadrantCode\": \"STAR\", \"quadrantName\": \"明星菜\", \"evidenceRefId\": \"ev-dish-opt_protect-8\", \"listPriceRevenue\": \"10160.00\", \"soldPortionsTotal\": \"254.00\", \"actualProfitAmount\": \"10015.22\", \"suggestedActionLabel\": \"继续主推\", \"blendedGrossMarginRateOnListPrice\": \"98.58%\"}], \"reason\": \"明星菜利润与销量贡献稳定，建议保供并维持推荐位\", \"priority\": 2, \"groupCode\": \"STABLE_PROMOTE\", \"groupName\": \"稳定主推\", \"suggestedAction\": \"继续主推\"}, {\"dishes\": [{\"dishId\": \"11\", \"reason\": \"销量低于本轮中位，实际利润不低于本轮中位（type123）\", \"dishName\": \"香煎青鱼\", \"quadrantCode\": \"POTENTIAL\", \"quadrantName\": \"潜力菜\", \"evidenceRefId\": \"ev-dish-opt_promotion-9\", \"listPriceRevenue\": \"9996.00\", \"soldPortionsTotal\": \"147.00\", \"actualProfitAmount\": \"9840.18\", \"suggestedActionLabel\": \"增加曝光\", \"blendedGrossMarginRateOnListPrice\": \"98.44%\"}], \"reason\": \"潜力菜利润效率较好但点单不足，可加强曝光与搭配\", \"priority\": 3, \"groupCode\": \"INCREASE_EXPOSURE\", \"groupName\": \"增加曝光\", \"suggestedAction\": \"增加曝光\"}, {\"dishes\": [{\"dishId\": \"5\", \"reason\": \"销量低于本轮中位，实际利润低于本轮中位（type123）；毛利率明显低于整体或利润贡献偏弱，建议重点复核成本、定价与备货\", \"dishName\": \"核桃芽菜西芹\", \"quadrantCode\": \"ELIMINATE\", \"quadrantName\": \"观察菜\", \"evidenceRefId\": \"ev-dish-opt_watch-10\", \"listPriceRevenue\": \"5800.00\", \"soldPortionsTotal\": \"232.00\", \"actualProfitAmount\": \"5651.52\", \"suggestedActionLabel\": \"重点复核\", \"blendedGrossMarginRateOnListPrice\": \"97.44%\"}], \"reason\": \"相对观察档（低销量低利润）先跟踪周期表现，再决定是否调整；不代表建议下架\", \"priority\": 4, \"groupCode\": \"WATCH_ADJUST\", \"groupName\": \"观察调整\", \"suggestedAction\": \"观察调整\"}], \"promotionDishes\": [{\"dishId\": \"11\", \"reason\": \"销量低于本轮中位，实际利润不低于本轮中位（type123）\", \"dishName\": \"香煎青鱼\", \"quadrantCode\": \"POTENTIAL\", \"quadrantName\": \"潜力菜\", \"evidenceRefId\": \"ev-dish-opt_promotion-9\", \"listPriceRevenue\": \"9996.00\", \"soldPortionsTotal\": \"147.00\", \"actualProfitAmount\": \"9840.18\", \"suggestedActionLabel\": \"增加曝光\", \"blendedGrossMarginRateOnListPrice\": \"98.44%\"}], \"watchListDishes\": [{\"dishId\": \"5\", \"reason\": \"销量低于本轮中位，实际利润低于本轮中位（type123）；毛利率明显低于整体或利润贡献偏弱，建议重点复核成本、定价与备货\", \"dishName\": \"核桃芽菜西芹\", \"quadrantCode\": \"ELIMINATE\", \"quadrantName\": \"观察菜\", \"evidenceRefId\": \"ev-dish-opt_watch-10\", \"listPriceRevenue\": \"5800.00\", \"soldPortionsTotal\": \"232.00\", \"actualProfitAmount\": \"5651.52\", \"suggestedActionLabel\": \"重点复核\", \"blendedGrossMarginRateOnListPrice\": \"97.44%\"}], \"costReviewDishes\": [{\"dishId\": \"8\", \"reason\": \"相对引流档（畅销低利），优先复核成本、用量与损耗\", \"dishName\": \"酸奶碗\", \"quadrantCode\": \"TRAFFIC\", \"quadrantName\": \"引流菜\", \"evidenceRefId\": \"ev-dish-opt_cost_review-7\", \"listPriceRevenue\": \"9270.00\", \"soldPortionsTotal\": \"309.00\", \"actualProfitAmount\": \"9041.34\", \"suggestedActionLabel\": \"复核成本\", \"blendedGrossMarginRateOnListPrice\": \"97.53%\"}], \"optimizationSummary\": \"本月菜单优化重点：先复核相对引流档（畅销低利）菜的成本与定价，同时稳定明星菜供应与推荐位；另有潜力菜可加强曝光；相对观察档菜品建议先观察再调整。\"}, \"keyFindings\": [\"酸奶碗销量最高，但理论成本与实际成本差距最大，成本管控是重点。\", \"椒麻鸡利润贡献最高，毛利率也最好，是菜单中的稳定盈利主力。\", \"香煎青鱼销量最低，但利润排名第二，有潜力通过提升曝光来增加收入。\"], \"mainSummary\": \"上个月汀兰餐厅整体毛利表现非常好，但四道菜中有两道菜的理论成本与实际成本差距较大，这是当前最值得关注的问题。\", \"focusSections\": [{\"dishes\": [{\"reason\": \"理论成本与实际成本差距全店最大，需先确认是核算口径问题还是实际用料差异\", \"dishName\": \"酸奶碗\", \"suggestedAction\": \"复核成本核算方式\", \"actualProfitAmount\": \"9041.34\", \"blendedGrossMarginRateOnListPrice\": \"97.53%\"}], \"reason\": \"成本偏差过大，会影响后续定价和利润判断的准确性\", \"sectionTitle\": \"优先处理：成本偏差最大的菜品\", \"sectionSummary\": \"酸奶碗的理论成本是3451.66元，但实际成本只有228.66元，两者差距非常大。这可能是成本核算方式不同，或者实际用料与标准配方有差异，需要先搞清楚原因。\", \"suggestedAction\": \"先与财务和厨房核对酸奶碗的成本计算逻辑\"}, {\"dishes\": [{\"reason\": \"销量、利润、毛利率三项指标均靠前，是菜单盈利核心\", \"dishName\": \"椒麻鸡\", \"suggestedAction\": \"保持现状\", \"actualProfitAmount\": \"10015.22\", \"blendedGrossMarginRateOnListPrice\": \"98.58%\"}], \"reason\": \"稳定盈利产品不宜频繁调整\", \"sectionTitle\": \"重点关注：稳定盈利主力\", \"sectionSummary\": \"椒麻鸡销量第二、利润第一，毛利率也是全店最高（98.58%），是菜单上最可靠的利润来源。建议保持现有出品和定价，不要轻易调整。\", \"suggestedAction\": \"维持椒麻鸡的出品标准和推荐位\"}, {\"dishes\": [{\"reason\": \"销量最低但利润高，说明每卖一份贡献不错，值得提升点单率\", \"dishName\": \"香煎青鱼\", \"suggestedAction\": \"增加曝光\", \"actualProfitAmount\": \"9840.18\", \"blendedGrossMarginRateOnListPrice\": \"98.44%\"}], \"reason\": \"利润表现好，销量有提升空间\", \"sectionTitle\": \"值得挖掘：销量低但利润不错的菜品\", \"sectionSummary\": \"香煎青鱼上个月只卖了147份，是四道菜中销量最低的，但利润排名第二，毛利率也超过98%。如果能在菜单上增加曝光，比如放到推荐位或搭配套餐，有潜力提升销量。\", \"suggestedAction\": \"评估是否将香煎青鱼放在更显眼的位置或与畅销菜搭配推广\"}], \"detailDataScope\": \"harness_only\", \"detailDataVisible\": false, \"presentationSource\": \"llm_expert_presentation\", \"supportingEvidence\": [{\"unit\": \"道\", \"value\": \"4\", \"displayLabel\": \"分析菜品数\"}, {\"unit\": \"元\", \"value\": \"35226\", \"displayLabel\": \"总销售额\"}, {\"unit\": \"份\", \"value\": \"942\", \"displayLabel\": \"总销量\"}, {\"unit\": \"\", \"value\": \"98.08%\", \"displayLabel\": \"综合毛利率\"}], \"capabilityBoundaryZh\": \"当前版本暂不提供最新采购价、外部市场比价、连续多周期趋势、跨门店排名和套餐点单组合分析。\"}, \"cardType\": \"MENU_ACTION_RECOMMENDATION_CARD\", \"subtitle\": \"基于四象限分层与销量、毛利、实际利润生成的优先级建议\", \"chartType\": \"PLAN\"}]', '{\"timeText\": \"2026-05-01～2026-05-31\", \"scopeText\": \"本门店\", \"storeText\": \"汀兰餐厅\", \"contextBar\": \"汀兰餐厅 · 05/01–05/31 · 本门店\", \"dateRangeText\": \"05/01–05/31\", \"permissionScopeText\": \"本门店\"}', '2026-06-02 19:24:42', '2026-06-02 19:24:42', 2);
