INSERT INTO `gb_ai_message` (`gb_ai_message_id`, `gb_ai_message_conversation_id`, `gb_ai_message_role`, `gb_ai_message_content`, `gb_ai_message_token_count`, `gb_ai_message_run_id`, `gb_ai_message_status`, `gb_ai_message_cards_json`, `gb_ai_message_context_summary_json`, `gb_ai_message_create_time`, `gb_ai_message_update_time`, `gb_ai_message_user_id`) VALUES (308, 91, 'assistant', '我没有识别清楚你想查库存的哪类数据，是库存总览、商品库存排行、门店库存排行，还是缺货/补货风险？', 0, 1780395386702, 'COMPLETED', NULL, '{\"timeText\": \"当前库存 · 最近7天（5月27日至6月2日）\", \"scopeText\": \"本门店\", \"storeText\": \"汀兰餐厅\", \"contextBar\": \"汀兰餐厅 · 当前库存 · 最近7天（5月27日至6月2日） · 本门店\", \"permissionScopeText\": \"本门店\"}', '2026-06-02 19:26:08', '2026-06-02 19:26:08', 2);
