INSERT INTO `gb_ai_message` (`gb_ai_message_id`, `gb_ai_message_conversation_id`, `gb_ai_message_role`, `gb_ai_message_content`, `gb_ai_message_token_count`, `gb_ai_message_run_id`, `gb_ai_message_status`, `gb_ai_message_cards_json`, `gb_ai_message_context_summary_json`, `gb_ai_message_create_time`, `gb_ai_message_update_time`, `gb_ai_message_user_id`) VALUES (310, 91, 'assistant', '椒麻鸡按当前销量与库存，大约还能支撑 2.09 天；最先不够的是「鲜三黄鸡」。详情见下方卡片。', 0, 1780395386703, 'COMPLETED', '[{\"title\": \"椒麻鸡 · 配料可支撑天数\", \"payload\": {\"dishId\": 6, \"summary\": {\"methodNote\": \"当前库存为实时快照（截至当前），不按问句时间窗过滤；日均销量/用量来自销量基线（最近7天（5月27日至6月2日））；可支撑天数 = 当前库存 ÷ 每日预计用量（每日预计用量 = 单份配方用量 × 日均销量）；基线期内无销量时不推算天数，但仍展示配方与当前库存。\", \"windowDays\": 7, \"salesPortions\": \"67\", \"salesBaselineDays\": 7, \"dailySalesPortions\": \"9.57\", \"salesBaselineLabel\": \"最近7天（5月27日至6月2日）\", \"inventoryDataSource\": {\"disId\": 2, \"source\": \"gb_department_goods_stock.queryGoodsStockListForMendianPeriod\", \"depFatherId\": 3, \"disGoodsWithRestCount\": 7}, \"salesBaselineSource\": \"DEFAULT_LAST_7_DAYS\", \"salesBaselineStopDate\": \"2026-06-02\", \"salesBaselineStartDate\": \"2026-05-27\"}, \"asOfDate\": \"2026-06-02\", \"dishName\": \"椒麻鸡\", \"knownGaps\": [\"shelf_life_batch_not_in_cover_days_p1\"], \"timeLabel\": \"当前库存（截至当前）\", \"dishCoverDays\": \"2.09\", \"ingredientRows\": [{\"coverDays\": \"2.09\", \"isBottleneck\": true, \"ingredientName\": \"鲜三黄鸡\", \"currentStockQty\": \"20\", \"recipeUnitPerDish\": \"1\", \"dailyExpectedUsageQty\": \"9.5714\"}], \"periodFlowLabel\": \"最近7天（5月27日至6月2日）\", \"salesBaselineDays\": 7, \"salesBaselineLabel\": \"最近7天（5月27日至6月2日）\", \"stockSnapshotLabel\": \"当前库存（截至当前）\", \"bottleneckCoverDays\": \"2.09\", \"ingredientRowFields\": [\"ingredientName\", \"recipeUnitPerDish\", \"currentStockQty\", \"currentStockQtyEmptyReason\", \"dailyExpectedUsageQty\", \"dailyExpectedUsageQtyEmptyReason\", \"coverDays\", \"coverDaysEmptyReason\", \"isBottleneck\"], \"salesBaselineSource\": \"DEFAULT